CREATE TABLE admin_operation_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NULL,operation VARCHAR(200) NOT NULL,target VARCHAR(255) NOT NULL,outcome VARCHAR(16) NOT NULL,http_status INT NOT NULL,trace_id VARCHAR(64) NULL,created_at DATETIME(6) NOT NULL,INDEX idx_audit_actor(actor_id,created_at),INDEX idx_audit_target(target,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
